CREATE TABLE ALUMNO (
    A_ID_ALUMNO NUMBER NOT NULL,
    A_NOMBRE    VARCHAR2(200) NOT NULL,
    A_TELEFONO  VARCHAR2(15),
    A_CLASE     VARCHAR2(1) NOT NULL,
    CONSTRAINT ALUMNO_PK PRIMARY KEY (A_ID_ALUMNO)
);

CREATE TABLE CALIFICACION (
    C_ID_ASIGNATURA NUMBER NOT NULL,
    C_ID_ALUMNO     NUMBER NOT NULL,
    C_NOTA          NUMBER NOT NULL,
    CONSTRAINT CALIFICACION_PK PRIMARY KEY (C_ID_ASIGNATURA, C_ID_ALUMNO)
);

preguntas.enunciado:
¿Cuál es la salida del siguiente código en Python?

set1 = {1, 1, 2}
set2 = {2, 3, 4}
result = set1 ^ set2
print(result)

¿Cuál es la salida del siguiente código en Python?

def fun(x, y):
    if x == 0:
        return y
    else:
        return fun(x - 1, x * y)

print(fun(4, 2))

opciones.a:
SELECT A_NOMBRE
FROM ALUMNO, CALIFICACION
WHERE A_ID_ALUMNO = C_ID_ALUMNO (+) AND C_ID_ASIGNATURA IS NULL;

opciones.b:
SELECT A_NOMBRE
FROM ALUMNO LEFT JOIN CALIFICACION ON A_ID_ALUMNO = C_ID_ALUMNO
WHERE C_ID_ALUMNO IS NULL;

opciones.c:
SELECT A_NOMBRE
FROM ALUMNO
WHERE NOT EXISTS (SELECT 1 FROM CALIFICACION WHERE A_ID_ALUMNO = C_ID_ALUMNO);

SELECT DISTINCT A_NOMBRE, A_TELEFONO, COUNT(*)
FROM ALUMNO, CALIFICACION
WHERE A_ID_ALUMNO = C_ID_ALUMNO AND NOTA<5;

opciones.b:
SELECT A_CLASE, MEDIA_CLASE(A_CLASE)
FROM ALUMNO
GROUP BY A_CLASE;

